const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;

pub const JCodecError = error{
    InvalidDimensions,
    AllocationFailed,
    CompressionFailed,
    DecompressionFailed,
    OutOfBounds,
};

pub const LatentConfig = struct {
    temporal_compression: usize,
    spatial_compression: usize,
    feature_dim: usize,
    max_frames: usize,
    height: usize,
    width: usize,
};

pub const ImplicitField = struct {
    weights: []f32,
    biases: []f32,
    layer_sizes: []usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, input_dim: usize, output_dim: usize, hidden_dim: usize, num_layers: usize) !ImplicitField {
        var layer_sizes = try allocator.alloc(usize, num_layers + 2);
        layer_sizes[0] = input_dim;
        for (1..num_layers + 1) |i| {
            layer_sizes[i] = hidden_dim;
        }
        layer_sizes[num_layers + 1] = output_dim;
        var total_weights: usize = 0;
        var total_biases: usize = 0;
        for (0..num_layers + 1) |i| {
            total_weights += layer_sizes[i] * layer_sizes[i + 1];
            total_biases += layer_sizes[i + 1];
        }
        const weights = try allocator.alloc(f32, total_weights);
        const biases = try allocator.alloc(f32, total_biases);
        var prng = std.rand.DefaultPrng.init(@intCast(std.time.milliTimestamp()));
        const random = prng.random();
        for (weights) |*w| {
            w.* = random.float(f32) * 0.2 - 0.1;
        }
        for (biases) |*b| {
            b.* = 0.0;
        }
        return ImplicitField{
            .weights = weights,
            .biases = biases,
            .layer_sizes = layer_sizes,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ImplicitField) void {
        self.allocator.free(self.weights);
        self.allocator.free(self.biases);
        self.allocator.free(self.layer_sizes);
    }

    pub fn forward(self: *const ImplicitField, input: []const f32, output: []f32) !void {
        var activations = try self.allocator.alloc(f32, self.layer_sizes[self.layer_sizes.len - 1]);
        defer self.allocator.free(activations);
        var prev_activations = try self.allocator.alloc(f32, self.layer_sizes[0]);
        defer self.allocator.free(prev_activations);
        @memcpy(prev_activations, input);
        var weight_offset: usize = 0;
        var bias_offset: usize = 0;
        for (0..self.layer_sizes.len - 1) |layer_idx| {
            const in_size = self.layer_sizes[layer_idx];
            const out_size = self.layer_sizes[layer_idx + 1];
            var curr_activations = try self.allocator.alloc(f32, out_size);
            defer if (layer_idx < self.layer_sizes.len - 2) self.allocator.free(curr_activations);
            for (0..out_size) |i| {
                var sum: f32 = self.biases[bias_offset + i];
                for (0..in_size) |j| {
                    sum += prev_activations[j] * self.weights[weight_offset + i * in_size + j];
                }
                if (layer_idx < self.layer_sizes.len - 2) {
                    curr_activations[i] = if (sum > 0) sum else sum * 0.01;
                } else {
                    curr_activations[i] = sum;
                }
            }
            if (layer_idx < self.layer_sizes.len - 2) {
                if (prev_activations.len != in_size) {
                    self.allocator.free(prev_activations);
                    prev_activations = try self.allocator.alloc(f32, out_size);
                }
                @memcpy(prev_activations, curr_activations);
            } else {
                @memcpy(output, curr_activations);
            }
            weight_offset += in_size * out_size;
            bias_offset += out_size;
        }
    }
};

pub const JCodec = struct {
    config: LatentConfig,
    encoder_field: ImplicitField,
    decoder_field: ImplicitField,
    allocator: Allocator,

    pub fn init(allocator: Allocator, config: LatentConfig) !JCodec {
        const encoder_input_dim: usize = 4;
        const encoder_output_dim: usize = config.feature_dim;
        const decoder_input_dim: usize = config.feature_dim + 3;
        const decoder_output_dim: usize = 3;
        const hidden_dim: usize = 256;
        const num_layers: usize = 4;
        var encoder_field = try ImplicitField.init(allocator, encoder_input_dim, encoder_output_dim, hidden_dim, num_layers);
        errdefer encoder_field.deinit();
        var decoder_field = try ImplicitField.init(allocator, decoder_input_dim, decoder_output_dim, hidden_dim, num_layers);
        return JCodec{
            .config = config,
            .encoder_field = encoder_field,
            .decoder_field = decoder_field,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *JCodec) void {
        self.encoder_field.deinit();
        self.decoder_field.deinit();
    }

    pub fn encode(self: *JCodec, video_frames: []const f32, latent_out: []f32) !void {
        const num_frames = self.config.max_frames;
        const height = self.config.height;
        const width = self.config.width;
        const feature_dim = self.config.feature_dim;
        const latent_temporal = num_frames / self.config.temporal_compression;
        const latent_height = height / self.config.spatial_compression;
        const latent_width = width / self.config.spatial_compression;
        if (video_frames.len < num_frames * height * width * 3) return JCodecError.InvalidDimensions;
        if (latent_out.len < latent_temporal * latent_height * latent_width * feature_dim) return JCodecError.InvalidDimensions;
        var input_coord = try self.allocator.alloc(f32, 4);
        defer self.allocator.free(input_coord);
        var feature_output = try self.allocator.alloc(f32, feature_dim);
        defer self.allocator.free(feature_output);
        for (0..latent_temporal) |t| {
            for (0..latent_height) |y| {
                for (0..latent_width) |x| {
                    const norm_t = @as(f32, @floatFromInt(t)) / @as(f32, @floatFromInt(latent_temporal));
                    const norm_y = @as(f32, @floatFromInt(y)) / @as(f32, @floatFromInt(latent_height));
                    const norm_x = @as(f32, @floatFromInt(x)) / @as(f32, @floatFromInt(latent_width));
                    input_coord[0] = norm_t * 2.0 - 1.0;
                    input_coord[1] = norm_y * 2.0 - 1.0;
                    input_coord[2] = norm_x * 2.0 - 1.0;
                    var avg_value: f32 = 0.0;
                    const t_start = t * self.config.temporal_compression;
                    const y_start = y * self.config.spatial_compression;
                    const x_start = x * self.config.spatial_compression;
                    for (0..self.config.temporal_compression) |dt| {
                        for (0..self.config.spatial_compression) |dy| {
                            for (0..self.config.spatial_compression) |dx| {
                                const frame_idx = t_start + dt;
                                const row_idx = y_start + dy;
                                const col_idx = x_start + dx;
                                if (frame_idx < num_frames and row_idx < height and col_idx < width) {
                                    const pixel_base = (frame_idx * height * width + row_idx * width + col_idx) * 3;
                                    avg_value += (video_frames[pixel_base] + video_frames[pixel_base + 1] + video_frames[pixel_base + 2]) / 3.0;
                                }
                            }
                        }
                    }
                    const patch_size = self.config.temporal_compression * self.config.spatial_compression * self.config.spatial_compression;
                    avg_value /= @as(f32, @floatFromInt(patch_size));
                    input_coord[3] = avg_value;
                    try self.encoder_field.forward(input_coord, feature_output);
                    const latent_base = (t * latent_height * latent_width + y * latent_width + x) * feature_dim;
                    for (0..feature_dim) |c| {
                        latent_out[latent_base + c] = feature_output[c];
                    }
                }
            }
        }
    }

    pub fn decode(self: *JCodec, latent_in: []const f32, video_out: []f32) !void {
        const num_frames = self.config.max_frames;
        const height = self.config.height;
        const width = self.config.width;
        const feature_dim = self.config.feature_dim;
        const latent_temporal = num_frames / self.config.temporal_compression;
        const latent_height = height / self.config.spatial_compression;
        const latent_width = width / self.config.spatial_compression;
        if (latent_in.len < latent_temporal * latent_height * latent_width * feature_dim) return JCodecError.InvalidDimensions;
        if (video_out.len < num_frames * height * width * 3) return JCodecError.InvalidDimensions;
        var decoder_input = try self.allocator.alloc(f32, feature_dim + 3);
        defer self.allocator.free(decoder_input);
        var rgb_output = try self.allocator.alloc(f32, 3);
        defer self.allocator.free(rgb_output);
        for (0..num_frames) |t| {
            for (0..height) |y| {
                for (0..width) |x| {
                    const latent_t = t / self.config.temporal_compression;
                    const latent_y = y / self.config.spatial_compression;
                    const latent_x = x / self.config.spatial_compression;
                    const norm_t = @as(f32, @floatFromInt(t)) / @as(f32, @floatFromInt(num_frames));
                    const norm_y = @as(f32, @floatFromInt(y)) / @as(f32, @floatFromInt(height));
                    const norm_x = @as(f32, @floatFromInt(x)) / @as(f32, @floatFromInt(width));
                    decoder_input[0] = norm_t * 2.0 - 1.0;
                    decoder_input[1] = norm_y * 2.0 - 1.0;
                    decoder_input[2] = norm_x * 2.0 - 1.0;
                    const latent_base = (latent_t * latent_height * latent_width + latent_y * latent_width + latent_x) * feature_dim;
                    for (0..feature_dim) |c| {
                        decoder_input[3 + c] = latent_in[latent_base + c];
                    }
                    try self.decoder_field.forward(decoder_input, rgb_output);
                    const pixel_base = (t * height * width + y * width + x) * 3;
                    for (0..3) |c| {
                        video_out[pixel_base + c] = math.clamp(rgb_output[c], 0.0, 1.0);
                    }
                }
            }
        }
    }

    pub fn getLatentSize(self: *const JCodec) usize {
        const latent_temporal = self.config.max_frames / self.config.temporal_compression;
        const latent_height = self.config.height / self.config.spatial_compression;
        const latent_width = self.config.width / self.config.spatial_compression;
        return latent_temporal * latent_height * latent_width * self.config.feature_dim;
    }
};
