const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;

pub const WorldStateError = error{
    TooManyObjects,
    ObjectNotFound,
    InvalidState,
    AllocationFailed,
};

pub const Vector3 = struct {
    x: f32,
    y: f32,
    z: f32,

    pub fn zero() Vector3 {
        return .{ .x = 0.0, .y = 0.0, .z = 0.0 };
    }

    pub fn add(a: Vector3, b: Vector3) Vector3 {
        return .{ .x = a.x + b.x, .y = a.y + b.y, .z = a.z + b.z };
    }

    pub fn scale(v: Vector3, s: f32) Vector3 {
        return .{ .x = v.x * s, .y = v.y * s, .z = v.z * s };
    }

    pub fn dot(a: Vector3, b: Vector3) f32 {
        return a.x * b.x + a.y * b.y + a.z * b.z;
    }

    pub fn magnitude(v: Vector3) f32 {
        return math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
    }

    pub fn normalize(v: Vector3) Vector3 {
        const mag = v.magnitude();
        if (mag < 1e-8) return v;
        return v.scale(1.0 / mag);
    }
};

pub const ObjectType = enum {
    sphere,
    box,
    plane,
    mesh,
    particle,
};

pub const Material = struct {
    albedo: [3]f32,
    roughness: f32,
    metallic: f32,
    emissive: f32,
};

pub const SceneObject = struct {
    id: u64,
    object_type: ObjectType,
    position: Vector3,
    velocity: Vector3,
    rotation: [4]f32,
    scale: Vector3,
    material: Material,
    active: bool,
};

pub const Relation = struct {
    from_id: u64,
    to_id: u64,
    relation_type: u8,
    strength: f32,
};

pub const JWorldState = struct {
    objects: []SceneObject,
    relations: std.ArrayList(Relation),
    global_features: []f32,
    num_objects: usize,
    max_objects: usize,
    feature_dim: usize,
    allocator: Allocator,
    next_id: u64,

    pub fn init(allocator: Allocator, max_objects: usize, feature_dim: usize) !JWorldState {
        var objects = try allocator.alloc(SceneObject, max_objects);
        for (objects) |*obj| {
            obj.* = .{
                .id = 0,
                .object_type = .sphere,
                .position = Vector3.zero(),
                .velocity = Vector3.zero(),
                .rotation = [_]f32{ 1.0, 0.0, 0.0, 0.0 },
                .scale = Vector3{ .x = 1.0, .y = 1.0, .z = 1.0 },
                .material = .{
                    .albedo = [_]f32{ 0.5, 0.5, 0.5 },
                    .roughness = 0.5,
                    .metallic = 0.0,
                    .emissive = 0.0,
                },
                .active = false,
            };
        }
        var global_features = try allocator.alloc(f32, feature_dim);
        @memset(global_features, 0.0);
        return JWorldState{
            .objects = objects,
            .relations = std.ArrayList(Relation).init(allocator),
            .global_features = global_features,
            .num_objects = 0,
            .max_objects = max_objects,
            .feature_dim = feature_dim,
            .allocator = allocator,
            .next_id = 1,
        };
    }

    pub fn deinit(self: *JWorldState) void {
        self.allocator.free(self.objects);
        self.relations.deinit();
