                    .velocity = Vector3.zero(),
                    .rotation = [_]f32{ 1.0, 0.0, 0.0, 0.0 },
                    .scale = Vector3{ .x = 1.0, .y = 1.0, .z = 1.0 },
                    .material = material,
                    .active = true,
                };
                self.num_objects += 1;
                return id;
            }
        }
        return WorldStateError.TooManyObjects;
    }

    pub fn removeObject(self: *JWorldState, id: u64) !void {
        for (self.objects) |*obj| {
            if (obj.active and obj.id == id) {
                obj.active = false;
                self.num_objects -= 1;
                return;
            }
        }
        return WorldStateError.ObjectNotFound;
    }

    pub fn getObject(self: *JWorldState, id: u64) ?*SceneObject {
        for (self.objects) |*obj| {
            if (obj.active and obj.id == id) {
                return obj;
            }
        }
        return null;
    }

