        if (features.len != self.feature_dim) return WorldStateError.InvalidState;
        @memcpy(self.global_features, features);
    }

    pub fn serializeState(self: *const JWorldState, buffer: []f32) !void {
        var offset: usize = 0;
        buffer[offset] = @floatFromInt(self.num_objects);
        offset += 1;
        for (self.objects) |obj| {
            if (!obj.active) continue;
            buffer[offset] = @floatFromInt(@intFromEnum(obj.object_type));
            buffer[offset + 1] = obj.position.x;
            buffer[offset + 2] = obj.position.y;
            buffer[offset + 3] = obj.position.z;
            buffer[offset + 4] = obj.velocity.x;
            buffer[offset + 5] = obj.velocity.y;
            buffer[offset + 6] = obj.velocity.z;
            buffer[offset + 7] = obj.rotation[0];
            buffer[offset + 8] = obj.rotation[1];
            buffer[offset + 9] = obj.rotation[2];
            buffer[offset + 10] = obj.rotation[3];
            buffer[offset + 11] = obj.scale.x;
            buffer[offset + 12] = obj.scale.y;
            buffer[offset + 13] = obj.scale.z;
            buffer[offset + 14] = obj.material.albedo[0];
            buffer[offset + 15] = obj.material.albedo[1];
            buffer[offset + 16] = obj.material.albedo[2];
            buffer[offset + 17] = obj.material.roughness;
            buffer[offset + 18] = obj.material.metallic;
            buffer[offset + 19] = obj.material.emissive;
            offset += 20;
        }
        const global_start = offset;
        for (self.global_features, 0..) |feat, i| {
            buffer[global_start + i] = feat;
        }
    }

    pub fn deserializeState(self: *JWorldState, buffer: []const f32) !void {
        var offset: usize = 0;
        const num_objects_f = buffer[offset];
        offset += 1;
        const num_to_load: usize = @intFromFloat(num_objects_f);
        for (self.objects) |*obj| {
            obj.active = false;
        }
        self.num_objects = 0;
        var loaded: usize = 0;
        while (loaded < num_to_load) : (loaded += 1) {
            const obj_type_val: u8 = @intFromFloat(buffer[offset]);
            const obj_type: ObjectType = @enumFromInt(obj_type_val);
            const position = Vector3{
                .x = buffer[offset + 1],
                .y = buffer[offset + 2],
                .z = buffer[offset + 3],
            };
            const velocity = Vector3{
                .x = buffer[offset + 4],
                .y = buffer[offset + 5],
                .z = buffer[offset + 6],
            };
            const rotation = [4]f32{
                buffer[offset + 7],
                buffer[offset + 8],
                buffer[offset + 9],
                buffer[offset + 10],
            };
            const scale = Vector3{
                .x = buffer[offset + 11],
                .y = buffer[offset + 12],
                .z = buffer[offset + 13],
            };
            const material = Material{
                .albedo = [3]f32{
                    buffer[offset + 14],
                    buffer[offset + 15],
                    buffer[offset + 16],
                },
                .roughness = buffer[offset + 17],
                .metallic = buffer[offset + 18],
                .emissive = buffer[offset + 19],
            };
            offset += 20;
            self.objects[loaded] = .{
                .id = self.next_id,
                .object_type = obj_type,
                .position = position,
                .velocity = velocity,
                .rotation = rotation,
                .scale = scale,
                .material = material,
                .active = true,
            };
            self.next_id += 1;
            self.num_objects += 1;
        }
        const global_start = offset;
        for (self.global_features, 0..) |*feat, i| {
            feat.* = buffer[global_start + i];
        }
    }

    pub fn getSerializedSize(self: *const JWorldState) usize {
        return 1 + self.max_objects * 20 + self.feature_dim;
    }
};
