            w.* = random.float(f32) * scale;
        }
        for (key_weights) |*w| {
            w.* = random.float(f32) * scale;
        }
        for (value_weights) |*w| {
            w.* = random.float(f32) * scale;
        }
        return AttentionHead{
            .query_weights = query_weights,
            .key_weights = key_weights,
            .value_weights = value_weights,
            .dim = dim,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *AttentionHead) void {
        self.allocator.free(self.query_weights);
        self.allocator.free(self.key_weights);
        self.allocator.free(self.value_weights);
    }

    pub fn forward(self: *const AttentionHead, input: []const f32, output: []f32) !void {
        const seq_len = input.len / self.dim;
        var queries = try self.allocator.alloc(f32, input.len);
        defer self.allocator.free(queries);
        var keys = try self.allocator.alloc(f32, input.len);
        defer self.allocator.free(keys);
        var values = try self.allocator.alloc(f32, input.len);
        defer self.allocator.free(values);
        for (0..seq_len) |i| {
            const in_offset = i * self.dim;
            const out_offset = i * self.dim;
            for (0..self.dim) |j| {
                var q_sum: f32 = 0.0;
                var k_sum: f32 = 0.0;
                var v_sum: f32 = 0.0;
                for (0..self.dim) |k| {
                    q_sum += input[in_offset + k] * self.query_weights[j * self.dim + k];
                    k_sum += input[in_offset + k] * self.key_weights[j * self.dim + k];
                    v_sum += input[in_offset + k] * self.value_weights[j * self.dim + k];
                }
                queries[out_offset + j] = q_sum;
                keys[out_offset + j] = k_sum;
                values[out_offset + j] = v_sum;
            }
        }
        var attention_scores = try self.allocator.alloc(f32, seq_len * seq_len);
        defer self.allocator.free(attention_scores);
        const scale_factor = math.sqrt(@as(f32, @floatFromInt(self.dim)));
        for (0..seq_len) |i| {
            var max_score: f32 = -math.inf(f32);
            for (0..seq_len) |j| {
                var score: f32 = 0.0;
                for (0..self.dim) |k| {
                    score += queries[i * self.dim + k] * keys[j * self.dim + k];
                }
                score /= scale_factor;
                attention_scores[i * seq_len + j] = score;
                if (score > max_score) max_score = score;
            }
            var sum_exp: f32 = 0.0;
            for (0..seq_len) |j| {
                const exp_val = math.exp(attention_scores[i * seq_len + j] - max_score);
                attention_scores[i * seq_len + j] = exp_val;
                sum_exp += exp_val;
            }
            for (0..seq_len) |j| {
                attention_scores[i * seq_len + j] /= sum_exp;
            }
        }
        for (0..seq_len) |i| {
            const out_offset = i * self.dim;
            for (0..self.dim) |j| {
                var weighted_sum: f32 = 0.0;
                for (0..seq_len) |k| {
                    weighted_sum += attention_scores[i * seq_len + k] * values[k * self.dim + j];
                }
                output[out_offset + j] = weighted_sum;
            }
        }
    }
};

pub const TransformerBlock = struct {
    attention: AttentionHead,
    ffn_weights1: []f32,
    ffn_weights2: []f32,
    ffn_bias1: []f32,
    ffn_bias2: []f32,
    layer_norm1_gamma: []f32,
    layer_norm1_beta: []f32,
    layer_norm2_gamma: []f32,
    layer_norm2_beta: []f32,
    dim: usize,
    ffn_dim: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dim: usize, ffn_dim: usize) !TransformerBlock {
        var attention = try AttentionHead.init(allocator, dim);
        errdefer attention.deinit();
        const ffn_weights1 = try allocator.alloc(f32, dim * ffn_dim);
        const ffn_weights2 = try allocator.alloc(f32, ffn_dim * dim);
        const ffn_bias1 = try allocator.alloc(f32, ffn_dim);
        const ffn_bias2 = try allocator.alloc(f32, dim);
        const layer_norm1_gamma = try allocator.alloc(f32, dim);
        const layer_norm1_beta = try allocator.alloc(f32, dim);
        const layer_norm2_gamma = try allocator.alloc(f32, dim);
        const layer_norm2_beta = try allocator.alloc(f32, dim);
        var prng = std.rand.DefaultPrng.init(@intCast(std.time.milliTimestamp()));
        const random = prng.random();
        const scale1 = math.sqrt(1.0 / @as(f32, @floatFromInt(dim)));
        const scale2 = math.sqrt(1.0 / @as(f32, @floatFromInt(ffn_dim)));
        for (ffn_weights1) |*w| {
            w.* = random.float(f32) * scale1;
        }
        for (ffn_weights2) |*w| {
            w.* = random.float(f32) * scale2;
        }
        @memset(ffn_bias1, 0.0);
        @memset(ffn_bias2, 0.0);
        for (layer_norm1_gamma) |*g| {
            g.* = 1.0;
        }
        @memset(layer_norm1_beta, 0.0);
        for (layer_norm2_gamma) |*g| {
            g.* = 1.0;
        }
        @memset(layer_norm2_beta, 0.0);
        return TransformerBlock{
            .attention = attention,
            .ffn_weights1 = ffn_weights1,
            .ffn_weights2 = ffn_weights2,
            .ffn_bias1 = ffn_bias1,
            .ffn_bias2 = ffn_bias2,
            .layer_norm1_gamma = layer_norm1_gamma,
            .layer_norm1_beta = layer_norm1_beta,
            .layer_norm2_gamma = layer_norm2_gamma,
            .layer_norm2_beta = layer_norm2_beta,
            .dim = dim,
            .ffn_dim = ffn_dim,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *TransformerBlock) void {
        self.attention.deinit();
        self.allocator.free(self.ffn_weights1);
        self.allocator.free(self.ffn_weights2);
        self.allocator.free(self.ffn_bias1);
        self.allocator.free(self.ffn_bias2);
        self.allocator.free(self.layer_norm1_gamma);
        self.allocator.free(self.layer_norm1_beta);
        self.allocator.free(self.layer_norm2_gamma);
        self.allocator.free(self.layer_norm2_beta);
    }

    fn layerNorm(input: []const f32, gamma: []const f32, beta: []const f32, output: []f32, epsilon: f32) void {
        const n = input.len;
        var mean: f32 = 0.0;
        for (input) |val| {
            mean += val;
        }
        mean /= @as(f32, @floatFromInt(n));
        var variance: f32 = 0.0;
        for (input) |val| {
            const diff = val - mean;
            variance += diff * diff;
        }
        variance /= @as(f32, @floatFromInt(n));
        const std_dev = math.sqrt(variance + epsilon);
        for (input, 0..) |val, i| {
            output[i] = gamma[i] * ((val - mean) / std_dev) + beta[i];
        }
    }

    pub fn forward(self: *const TransformerBlock, input: []const f32, output: []f32) !void {
        const seq_len = input.len / self.dim;
        var attn_output = try self.allocator.alloc(f32, input.len);
        defer self.allocator.free(attn_output);
        try self.attention.forward(input, attn_output);
        var residual1 = try self.allocator.alloc(f32, input.len);
        defer self.allocator.free(residual1);
        for (input, 0..) |val, i| {
            residual1[i] = val + attn_output[i];
        }
        var norm1_output = try self.allocator.alloc(f32, input.len);
        defer self.allocator.free(norm1_output);
        for (0..seq_len) |i| {
            const offset = i * self.dim;
            layerNorm(residual1[offset .. offset + self.dim], self.layer_norm1_gamma, self.layer_norm1_beta, norm1_output[offset .. offset + self.dim], 1e-5);
        }
        var ffn_intermediate = try self.allocator.alloc(f32, seq_len * self.ffn_dim);
        defer self.allocator.free(ffn_intermediate);
        for (0..seq_len) |i| {
            const in_offset = i * self.dim;
            const out_offset = i * self.ffn_dim;
            for (0..self.ffn_dim) |j| {
                var sum: f32 = self.ffn_bias1[j];
                for (0..self.dim) |k| {
                    sum += norm1_output[in_offset + k] * self.ffn_weights1[k * self.ffn_dim + j];
                }
                ffn_intermediate[out_offset + j] = if (sum > 0) sum else 0;
            }
        }
        var ffn_output = try self.allocator.alloc(f32, input.len);
        defer self.allocator.free(ffn_output);
        for (0..seq_len) |i| {
            const in_offset = i * self.ffn_dim;
            const out_offset = i * self.dim;
            for (0..self.dim) |j| {
                var sum: f32 = self.ffn_bias2[j];
                for (0..self.ffn_dim) |k| {
                    sum += ffn_intermediate[in_offset + k] * self.ffn_weights2[k * self.dim + j];
                }
                ffn_output[out_offset + j] = sum;
            }
        }
        var residual2 = try self.allocator.alloc(f32, input.len);
        defer self.allocator.free(residual2);
        for (norm1_output, 0..) |val, i| {
            residual2[i] = val + ffn_output[i];
        }
        for (0..seq_len) |i| {
            const offset = i * self.dim;
            layerNorm(residual2[offset .. offset + self.dim], self.layer_norm2_gamma, self.layer_norm2_beta, output[offset .. offset + self.dim], 1e-5);
        }
    }
};

pub const JEvolver = struct {
    transformer_blocks: []TransformerBlock,
    num_blocks: usize,
    state_dim: usize,
    ffn_dim: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, state_dim: usize, num_blocks: usize) !JEvolver {
        const ffn_dim = state_dim * 4;
        var transformer_blocks = try allocator.alloc(TransformerBlock, num_blocks);
        var initialized: usize = 0;
        errdefer {
            for (0..initialized) |i| {
                transformer_blocks[i].deinit();
            }
            allocator.free(transformer_blocks);
        }
        for (transformer_blocks) |*block| {
            block.* = try TransformerBlock.init(allocator, state_dim, ffn_dim);
            initialized += 1;
        }
        return JEvolver{
            .transformer_blocks = transformer_blocks,
            .num_blocks = num_blocks,
            .state_dim = state_dim,
            .ffn_dim = ffn_dim,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *JEvolver) void {
        for (self.transformer_blocks) |*block| {
            block.deinit();
        }
        self.allocator.free(self.transformer_blocks);
    }

    pub fn evolve(self: *JEvolver, current_state: []const f32, next_state: []f32, delta_time: f32) !void {
        if (current_state.len != next_state.len) return EvolverError.InvalidState;
        var intermediate = try self.allocator.alloc(f32, current_state.len);
        defer self.allocator.free(intermediate);
        @memcpy(intermediate, current_state);
        var temp_buffer = try self.allocator.alloc(f32, current_state.len);
        defer self.allocator.free(temp_buffer);
        for (self.transformer_blocks) |*block| {
            try block.forward(intermediate, temp_buffer);
            @memcpy(intermediate, temp_buffer);
        }
        for (current_state, 0..) |val, i| {
            const delta = intermediate[i] - val;
            next_state[i] = val + delta * delta_time;
        }
    }

    pub fn evolveWorldState(self: *JEvolver, world_state: *JWorldState, delta_time: f32) !void {
        const state_size = world_state.getSerializedSize();
        var current_buffer = try self.allocator.alloc(f32, state_size);
        defer self.allocator.free(current_buffer);
        var next_buffer = try self.allocator.alloc(f32, state_size);
        defer self.allocator.free(next_buffer);
        try world_state.serializeState(current_buffer);
        try self.evolve(current_buffer, next_buffer, delta_time);
        try world_state.deserializeState(next_buffer);
        for (world_state.objects) |*obj| {
            if (!obj.active) continue;
            obj.position = obj.position.add(obj.velocity.scale(delta_time));
            const gravity = Vector3{ .x = 0.0, .y = -9.8, .z = 0.0 };
            obj.velocity = obj.velocity.add(gravity.scale(delta_time));
            if (obj.position.y < 0.0) {
                obj.position.y = 0.0;
                obj.velocity.y = -obj.velocity.y * 0.8;
            }
        }
    }
};
