pub const JGrounder = struct {
    allocator: Allocator,
    object_vocab: std.StringHashMap(ObjectType),
    color_vocab: std.StringHashMap([3]f32),

    pub fn init(allocator: Allocator) !JGrounder {
        var object_vocab = std.StringHashMap(ObjectType).init(allocator);
        try object_vocab.put("sphere", .sphere);
        try object_vocab.put("ball", .sphere);
        try object_vocab.put("box", .box);
        try object_vocab.put("cube", .box);
        try object_vocab.put("plane", .plane);
        try object_vocab.put("ground", .plane);
        try object_vocab.put("floor", .plane);
        var color_vocab = std.StringHashMap([3]f32).init(allocator);
        try color_vocab.put("red", [3]f32{ 1.0, 0.0, 0.0 });
        try color_vocab.put("green", [3]f32{ 0.0, 1.0, 0.0 });
        try color_vocab.put("blue", [3]f32{ 0.0, 0.0, 1.0 });
        try color_vocab.put("yellow", [3]f32{ 1.0, 1.0, 0.0 });
        try color_vocab.put("white", [3]f32{ 1.0, 1.0, 1.0 });
        try color_vocab.put("black", [3]f32{ 0.0, 0.0, 0.0 });
        try color_vocab.put("gray", [3]f32{ 0.5, 0.5, 0.5 });
        return JGrounder{
            .allocator = allocator,
            .object_vocab = object_vocab,
            .color_vocab = color_vocab,
        };
    }

    pub fn deinit(self: *JGrounder) void {
        self.object_vocab.deinit();
        self.color_vocab.deinit();
    }

    pub fn parsePrompt(self: *JGrounder, prompt: []const u8) !SceneDescription {
        var scene = SceneDescription.init(self.allocator);
        errdefer scene.deinit();
        var iter = mem.tokenize(u8, prompt, " \t\n,.");
        var position_x: f32 = 0.0;
        var position_y: f32 = 1.0;
        var position_z: f32 = 0.0;
        var current_color: [3]f32 = [_]f32{ 0.7, 0.7, 0.7 };
        while (iter.next()) |word| {
            var lower_word = try self.allocator.alloc(u8, word.len);
            defer self.allocator.free(lower_word);
            for (word, 0..) |c, i| {
                lower_word[i] = std.ascii.toLower(c);
            }
            if (self.color_vocab.get(lower_word)) |color| {
                current_color = color;
            } else if (self.object_vocab.get(lower_word)) |obj_type| {
                const name = try self.allocator.dupe(u8, lower_word);
                try scene.objects.append(.{
                    .name = name,
                    .object_type = obj_type,
                    .position = Vector3{ .x = position_x, .y = position_y, .z = position_z },
                    .color = current_color,
                    .size = 1.0,
                });
                position_x += 2.0;
                if (position_x > 8.0) {
                    position_x = 0.0;
                    position_z += 2.0;
                }
            }
        }
        return scene;
    }

    pub fn groundToWorldState(self: *JGrounder, scene: *const SceneDescription, world_state: *JWorldState) !void {
        for (scene.objects.items) |obj_desc| {
            const material = Material{
                .albedo = obj_desc.color,
                .roughness = 0.5,
                .metallic = 0.0,
                .emissive = 0.0,
            };
            _ = try world_state.addObject(obj_desc.object_type, obj_desc.position, material);
        }
        const features = try self.allocator.alloc(f32, world_state.feature_dim);
        defer self.allocator.free(features);
        @memset(features, 0.0);
        const num_objects_f = @as(f32, @floatFromInt(scene.objects.items.len));
        if (world_state.feature_dim > 0) {
            features[0] = num_objects_f / 10.0;
        }
        if (world_state.feature_dim > 1) {
            features[1] = 0.5;
        }
        try world_state.updateGlobalFeatures(features);
    }

    pub fn generateSceneProgram(self: *JGrounder, prompt: []const u8, world_state: *JWorldState) !void {
        var scene = try self.parsePrompt(prompt);
        defer scene.deinit();
        try self.groundToWorldState(&scene, world_state);
    }
};
