const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;
const JWorldState = @import("jaide_world_state.zig").JWorldState;
const Vector3 = @import("jaide_world_state.zig").Vector3;

pub const RendererError = error{
    InvalidDimensions,
    AllocationFailed,
    RenderFailed,
};

pub const Ray = struct {
    origin: Vector3,
    direction: Vector3,
};

pub const HitRecord = struct {
    hit: bool,
    distance: f32,
    position: Vector3,
    normal: Vector3,
    color: [3]f32,
