pub const Camera = struct {
    position: Vector3,
    forward: Vector3,
    up: Vector3,
    right: Vector3,
    fov: f32,

    pub fn init(position: Vector3, look_at: Vector3, fov: f32) Camera {
        const forward = look_at.add(position.scale(-1.0)).normalize();
        const world_up = Vector3{ .x = 0.0, .y = 1.0, .z = 0.0 };
        const right_x = forward.y * world_up.z - forward.z * world_up.y;
        const right_y = forward.z * world_up.x - forward.x * world_up.z;
        const right_z = forward.x * world_up.y - forward.y * world_up.x;
        const right = Vector3{ .x = right_x, .y = right_y, .z = right_z }.normalize();
        const up_x = right.y * forward.z - right.z * forward.y;
        const up_y = right.z * forward.x - right.x * forward.z;
        const up_z = right.x * forward.y - right.y * forward.x;
        const up = Vector3{ .x = up_x, .y = up_y, .z = up_z }.normalize();
        return Camera{
            .position = position,
            .forward = forward,
            .up = up,
            .right = right,
            .fov = fov,
        };
    }

    pub fn getRay(self: *const Camera, u: f32, v: f32, aspect_ratio: f32) Ray {
        const half_height = math.tan(self.fov * 0.5 * math.pi / 180.0);
        const half_width = aspect_ratio * half_height;
        const offset_right = self.right.scale((u - 0.5) * 2.0 * half_width);
        const offset_up = self.up.scale((v - 0.5) * 2.0 * half_height);
        const direction = self.forward.add(offset_right).add(offset_up).normalize();
        return Ray{
            .origin = self.position,
            .direction = direction,
        };
    }
};

pub const JRenderer = struct {
    width: usize,
    height: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, width: usize, height: usize) !JRenderer {
        return JRenderer{
            .width = width,
            .height = height,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *JRenderer) void {
        _ = self;
    }

    fn intersectSphere(ray: Ray, center: Vector3, radius: f32) HitRecord {
        const oc = ray.origin.add(center.scale(-1.0));
        const a = ray.direction.dot(ray.direction);
        const b = 2.0 * oc.dot(ray.direction);
        const c = oc.dot(oc) - radius * radius;
        const discriminant = b * b - 4.0 * a * c;
        if (discriminant < 0.0) {
            return .{
                .hit = false,
                .distance = math.inf(f32),
                .position = Vector3.zero(),
                .normal = Vector3.zero(),
                .color = [_]f32{ 0.0, 0.0, 0.0 },
            };
        }
        const t = (-b - math.sqrt(discriminant)) / (2.0 * a);
        if (t < 0.001) {
            return .{
                .hit = false,
                .distance = math.inf(f32),
                .position = Vector3.zero(),
                .normal = Vector3.zero(),
                .color = [_]f32{ 0.0, 0.0, 0.0 },
            };
        }
        const hit_pos = ray.origin.add(ray.direction.scale(t));
        const normal = hit_pos.add(center.scale(-1.0)).normalize();
        return .{
            .hit = true,
            .distance = t,
            .position = hit_pos,
            .normal = normal,
            .color = [_]f32{ 1.0, 1.0, 1.0 },
        };
    }

    fn intersectPlane(ray: Ray, plane_y: f32) HitRecord {
        if (math.fabs(ray.direction.y) < 0.001) {
            return .{
                .hit = false,
                .distance = math.inf(f32),
                .position = Vector3.zero(),
                .normal = Vector3.zero(),
                .color = [_]f32{ 0.0, 0.0, 0.0 },
            };
        }
        const t = (plane_y - ray.origin.y) / ray.direction.y;
        if (t < 0.001) {
            return .{
                .hit = false,
                .distance = math.inf(f32),
                .position = Vector3.zero(),
                .normal = Vector3.zero(),
                .color = [_]f32{ 0.0, 0.0, 0.0 },
            };
        }
        const hit_pos = ray.origin.add(ray.direction.scale(t));
        return .{
            .hit = true,
            .distance = t,
            .position = hit_pos,
            .normal = Vector3{ .x = 0.0, .y = 1.0, .z = 0.0 },
            .color = [_]f32{ 0.5, 0.5, 0.5 },
        };
    }

    fn traceRay(ray: Ray, world_state: *const JWorldState) HitRecord {
        var closest_hit = HitRecord{
            .hit = false,
            .distance = math.inf(f32),
            .position = Vector3.zero(),
            .normal = Vector3.zero(),
            .color = [_]f32{ 0.0, 0.0, 0.0 },
        };
        for (world_state.objects) |obj| {
            if (!obj.active) continue;
            var hit: HitRecord = undefined;
            switch (obj.object_type) {
                .sphere => {
                    hit = intersectSphere(ray, obj.position, obj.scale.x);
                },
                .plane => {
                    hit = intersectPlane(ray, obj.position.y);
                },
                else => continue,
            }
            if (hit.hit and hit.distance < closest_hit.distance) {
                closest_hit = hit;
                closest_hit.color = obj.material.albedo;
            }
        }
        return closest_hit;
    }

    fn shadeHit(hit: HitRecord) [3]f32 {
        if (!hit.hit) {
            return [_]f32{ 0.5, 0.7, 1.0 };
        }
        const light_dir = Vector3{ .x = 0.5, .y = 1.0, .z = 0.3 }.normalize();
        const diffuse = math.max(0.0, hit.normal.dot(light_dir));
        const ambient: f32 = 0.2;
        const intensity = ambient + diffuse * 0.8;
        return [_]f32{
            hit.color[0] * intensity,
            hit.color[1] * intensity,
            hit.color[2] * intensity,
        };
    }

    pub fn renderFrame(self: *JRenderer, world_state: *const JWorldState, camera: Camera, output: []f32) !void {
        if (output.len < self.width * self.height * 3) return RendererError.InvalidDimensions;
        const aspect_ratio = @as(f32, @floatFromInt(self.width)) / @as(f32, @floatFromInt(self.height));
        for (0..self.height) |y| {
            for (0..self.width) |x| {
                const u = @as(f32, @floatFromInt(x)) / @as(f32, @floatFromInt(self.width));
                const v = @as(f32, @floatFromInt(y)) / @as(f32, @floatFromInt(self.height));
                const ray = camera.getRay(u, v, aspect_ratio);
                const hit = traceRay(ray, world_state);
                const color = shadeHit(hit);
                const pixel_idx = (y * self.width + x) * 3;
                output[pixel_idx] = color[0];
                output[pixel_idx + 1] = color[1];
                output[pixel_idx + 2] = color[2];
            }
        }
    }

    pub fn renderVideo(self: *JRenderer, world_state: *const JWorldState, num_frames: usize, output: []f32) !void {
        if (output.len < num_frames * self.width * self.height * 3) return RendererError.InvalidDimensions;
        for (0..num_frames) |frame_idx| {
            const t = @as(f32, @floatFromInt(frame_idx)) / @as(f32, @floatFromInt(num_frames));
            const angle = t * 2.0 * math.pi;
            const cam_x = 10.0 * math.cos(angle);
            const cam_z = 10.0 * math.sin(angle);
            const camera = Camera.init(Vector3{ .x = cam_x, .y = 5.0, .z = cam_z }, Vector3{ .x = 0.0, .y = 0.0, .z = 0.0 }, 60.0);
            const frame_offset = frame_idx * self.width * self.height * 3;
            try self.renderFrame(world_state, camera, output[frame_offset .. frame_offset + self.width * self.height * 3]);
        }
    }
};
