const std = @import("std");
const mem = std.mem;
const Allocator = mem.Allocator;
const JCodec = @import("jaide_video_codec.zig").JCodec;
const LatentConfig = @import("jaide_video_codec.zig").LatentConfig;
const JWorldState = @import("jaide_world_state.zig").JWorldState;
const Vector3 = @import("jaide_world_state.zig").Vector3;
const JEvolver = @import("jaide_evolver.zig").JEvolver;
const JGrounder = @import("jaide_grounder.zig").JGrounder;
const JRenderer = @import("jaide_renderer.zig").JRenderer;
const Camera = @import("jaide_renderer.zig").Camera;

pub const JAIDEVideoWorldModel = struct {
    codec: JCodec,
    world_state: JWorldState,
    evolver: JEvolver,
    grounder: JGrounder,
    renderer: JRenderer,
    allocator: Allocator,

    pub fn init(allocator: Allocator) !JAIDEVideoWorldModel {
        const config = LatentConfig{
            .temporal_compression = 4,
            .spatial_compression = 8,
            .feature_dim = 16,
            .max_frames = 64,
            .height = 256,
            .width = 256,
        };
        var codec = try JCodec.init(allocator, config);
        errdefer codec.deinit();
        var world_state = try JWorldState.init(allocator, 64, 512);
        errdefer world_state.deinit();
        var evolver = try JEvolver.init(allocator, 512, 4);
        errdefer evolver.deinit();
        var grounder = try JGrounder.init(allocator);
        errdefer grounder.deinit();
        var renderer = try JRenderer.init(allocator, 256, 256);
        return JAIDEVideoWorldModel{
            .codec = codec,
            .world_state = world_state,
            .evolver = evolver,
            .grounder = grounder,
            .renderer = renderer,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *JAIDEVideoWorldModel) void {
        self.codec.deinit();
        self.world_state.deinit();
        self.evolver.deinit();
        self.grounder.deinit();
        self.renderer.deinit();
    }

    pub fn generateVideoFromText(self: *JAIDEVideoWorldModel, prompt: []const u8, num_frames: usize) ![]f32 {
        try self.grounder.generateSceneProgram(prompt, &self.world_state);
        const frame_size = self.codec.config.height * self.codec.config.width * 3;
        const video_size = num_frames * frame_size;
        var video_output = try self.allocator.alloc(f32, video_size);
        errdefer self.allocator.free(video_output);
        const delta_time: f32 = 1.0 / 30.0;
        for (0..num_frames) |frame_idx| {
            if (frame_idx > 0) {
                try self.evolver.evolveWorldState(&self.world_state, delta_time);
            }
            const frame_offset = frame_idx * frame_size;
            const camera = Camera.init(Vector3{ .x = 8.0, .y = 5.0, .z = 8.0 }, Vector3{ .x = 0.0, .y = 0.0, .z = 0.0 }, 60.0);
            try self.renderer.renderFrame(&self.world_state, camera, video_output[frame_offset .. frame_offset + frame_size]);
        }
        return video_output;
    }

    pub fn encodeVideoToLatent(self: *JAIDEVideoWorldModel, video_frames: []const f32) ![]f32 {
        const latent_size = self.codec.getLatentSize();
        var latent = try self.allocator.alloc(f32, latent_size);
        errdefer self.allocator.free(latent);
        try self.codec.encode(video_frames, latent);
        return latent;
    }

    pub fn decodeLatentToVideo(self: *JAIDEVideoWorldModel, latent: []const f32) ![]f32 {
        const video_size = self.codec.config.max_frames * self.codec.config.height * self.codec.config.width * 3;
        var video = try self.allocator.alloc(f32, video_size);
        errdefer self.allocator.free(video);
        try self.codec.decode(latent, video);
        return video;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    var model = try JAIDEVideoWorldModel.init(allocator);
    defer model.deinit();
    const prompt = "red sphere blue box green plane";
    const num_frames: usize = 30;
    const video = try model.generateVideoFromText(prompt, num_frames);
    defer allocator.free(video);
    std.debug.print("Generated video with {} frames\n", .{num_frames});
    const latent = try model.encodeVideoToLatent(video);
    defer allocator.free(latent);
    std.debug.print("Encoded to latent size: {}\n", .{latent.len});
    const decoded = try model.decodeLatentToVideo(latent);
    defer allocator.free(decoded);
    std.debug.print("Decoded back to video size: {}\n", .{decoded.len});
}
